import multiprocessing
import time

def test():
    data = {"a": ["hello", "hello", "hi chatgpt"], "b": [3, 1, 3]}
    df = pd.DataFrame.from_dict(data)

    for col in df:
        df[col] = df[col].drop_duplicates().reset_index(drop=True)
    return df

if __name__ == '__main__':
    df = test()
    for j in range(500):
        p = multiprocessing.Process(target=lambda: time.sleep(1))
        p.start()
